EXPECTED_ARCHIVE_SHA256 = "03e242c632ed5a478be2541e99bd7aa75524bd82f72af8f35694cea8ace59244"
TARGET = pathlib.Path.cwd() / "sprite_22_bottlenecks_code"
if TARGET.exists():
    sys.exit("STOP: sprite_22_bottlenecks_code already exists. Nothing overwritten.")
try:
    packed = base64.b64decode("".join(DATA.split()), validate=True)
    if hashlib.sha256(packed).hexdigest() != EXPECTED_ARCHIVE_SHA256:
        raise ValueError("Copy interrupted or modified. Recopy the entire block; nothing installed.")
    unpacked = lzma.decompress(packed, format=lzma.FORMAT_XZ)
except Exception as exc:
    sys.exit("Installation data invalid: " + str(exc))
tmp = pathlib.Path(tempfile.mkdtemp(prefix="sprite22-tmp-", dir=pathlib.Path.cwd()))
root_name = "sprite_22_bottlenecks_code/"
try:
    with tarfile.open(fileobj=io.BytesIO(unpacked), mode="r:") as archive:
        members = archive.getmembers()
        if len(members) != 39:
            raise RuntimeError("Unexpected source file count")
        for entry in members:
            name = entry.name
            if not entry.isfile() or not name.startswith(root_name):
                raise RuntimeError("Unexpected archive entry")
            relative = pathlib.PurePosixPath(name[len(root_name):])
            if relative.is_absolute() or ".." in relative.parts or not relative.parts:
                raise RuntimeError("Unsafe archive path")
            target = tmp.joinpath(*relative.parts)
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(archive.extractfile(entry).read())
    manifest = (tmp / "SHA256SUMS").read_text().splitlines()
    for line in manifest:
        digest, relative = line.split(maxsplit=1)
        f = tmp / relative
        if not f.is_file() or hashlib.sha256(f.read_bytes()).hexdigest() != digest:
            raise RuntimeError("Source integrity failed for " + relative)
    if len(manifest) != 38:
        raise RuntimeError("Unexpected checksum count")
    tmp.rename(TARGET)
except Exception:
    shutil.rmtree(tmp, ignore_errors=True)
    raise
print("Sprite source installed:", TARGET)
print("All source SHA-256 checks passed.")
print("No Cloudflare changes, ClawHunt bids, claims, or solves were made.")
node = shutil.which("node")
if not node:
    print("Node.js 22+ not found. Install Node.js 22+ to run tests.")
else:
    major = int(subprocess.check_output([node,"-p","process.versions.node.split('.')[0]"],text=True).strip())
    if major < 22:
        print("Node.js 22+ required for tests. Current major:", major)
    else:
        print("Running package tests...")
        p = subprocess.run(["npm", "test"],cwd=TARGET)
        if p.returncode != 0:
            sys.exit("Installed, but tests failed. Live bidding remains disabled.")
        print("Source and tests installed successfully. Live bidding remains disabled.")
